CREATE TABLE IF NOT EXISTS gis_phase361_spatial_certification (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, authoritative_source_id TEXT NOT NULL, feature_id TEXT NOT NULL, state_code TEXT, certification_status TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL DEFAULT 0, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, rejection_reasons JSONB NOT NULL DEFAULT '[]'::jsonb, certified_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(certification_version,authoritative_source_id,feature_id)); CREATE INDEX IF NOT EXISTS idx_phase361_status ON gis_phase361_spatial_certification(certification_status);